foreach;?></select></label><label>AI refresh batch<input type="number" min="1" max="3" name="ai_batch_size" value="<?=(int)$s['ai_batch_size']?>"></label><button>Save Settings</button></form><p class="hint"><?php if($aiReady):?>Google AI Studio is ready. AI copy is cached per business and regenerated only when requested/stale.<?php else:?>Google AI Studio is not configured. Pages still work with factual copy and the ShahkotPK business AI concierge; configure Gemini in AI Copilot to generate enhanced copy.<?php endif;?></p></section><section class="panel"><div class="panel-head"><div><span>BUSINESS WEBSITES</span><h2>Design each listing</h2></div><form method="get"><input name="q" value="<?=sk1130_h($search)?>" placeholder="Search business…"><button>Search</button></form></div><form method="post" class="batch"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><button name="action" value="batch">Refresh stale AI copy batch</button></form><div class="business-list"><?php foreach($rows as $b):$bid=(int)$b['id'];$p=sk1130_profile($bid);$theme=sk1130_theme($b,$p);?><article><div class="business-main"><div class="avatar"><?=sk1130_h(mb_substr((string)sk1130_business_value($b,['name'],'B'),0,1))?></div><div><small><?=sk1130_h(sk1130_category($b))?></small><h3><?=sk1130_h((string)sk1130_business_value($b,['name'],'Business'))?></h3><p>Auto theme: <b><?=sk1130_h(ucfirst($theme))?></b><?php if(sk1130_source_stale($b,$p)):?> · <em>AI copy stale</em><?php endif;?></p><a href="/business-site.php?id=<?=$bid?>" target="_blank">Preview website ↗</a> · <a href="/admin/business-website-builder.php?business_id=<?=$bid?>">Website Builder</a></div></div><form method="post" class="business-controls"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="action" value="profile"><label class="check"><input type="checkbox" name="enabled" value="1" <?=!empty($p['enabled'])?'